// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (GET /assets)
	ListAssets(w http.ResponseWriter, r *http.Request)
	// UploadAsset Upload an image (PNG, JPEG or GIF); identical files are stored once
	// (POST /assets)
	UploadAsset(w http.ResponseWriter, r *http.Request)

	// (DELETE /assets/{id})
	DeleteAsset(w http.ResponseWriter, r *http.Request, id AssetID)
	// PreviewAsset Show an image as a device model would display it
	// (POST /assets/{id}/preview)
	PreviewAsset(w http.ResponseWriter, r *http.Request, id AssetID)

	// (GET /components)
	ListComponents(w http.ResponseWriter, r *http.Request)

	// (POST /components)
	CreateComponent(w http.ResponseWriter, r *http.Request)
	// PreviewComponent Render a (possibly unsaved) component on its own with sample data
	// (POST /components/preview)
	PreviewComponent(w http.ResponseWriter, r *http.Request)

	// (DELETE /components/{id})
	DeleteComponent(w http.ResponseWriter, r *http.Request, id ComponentID)

	// (GET /components/{id})
	GetComponent(w http.ResponseWriter, r *http.Request, id ComponentID)
	// UpdateComponent Update a user component and re-render the screens that use it
	// (PUT /components/{id})
	UpdateComponent(w http.ResponseWriter, r *http.Request, id ComponentID)
	// DuplicateComponent Copy a component (e.g. a built-in) into an editable user component
	// (POST /components/{id}/duplicate)
	DuplicateComponent(w http.ResponseWriter, r *http.Request, id ComponentID)

	// (GET /connector-types)
	ListConnectorTypes(w http.ResponseWriter, r *http.Request)

	// (GET /connectors)
	ListConnectors(w http.ResponseWriter, r *http.Request)

	// (POST /connectors)
	CreateConnector(w http.ResponseWriter, r *http.Request)
	// DeleteConnector Delete a connector and every binding that uses it
	// (DELETE /connectors/{id})
	DeleteConnector(w http.ResponseWriter, r *http.Request, id ConnectorID)
	// UpdateConnector Update name and settings; secret fields left empty keep their stored value
	// (PUT /connectors/{id})
	UpdateConnector(w http.ResponseWriter, r *http.Request, id ConnectorID)
	// TestConnector Fetch once with the given params (not cached)
	// (POST /connectors/{id}/test)
	TestConnector(w http.ResponseWriter, r *http.Request, id ConnectorID)

	// (GET /device-models)
	ListDeviceModels(w http.ResponseWriter, r *http.Request)
	// SetToneCurve Save a model's gray tone curve; its screens re-render
	// (PUT /device-models/{id}/tone-curve)
	SetToneCurve(w http.ResponseWriter, r *http.Request, id ModelID)
	// PreviewToneCurve Render the calibration pattern with an unsaved curve
	// (POST /device-models/{id}/tone-curve/preview)
	PreviewToneCurve(w http.ResponseWriter, r *http.Request, id ModelID)
	// ListDevices All devices, pending first
	// (GET /devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// DeleteDevice Remove a device (it reappears as pending when it next contacts the server)
	// (DELETE /devices/{id})
	DeleteDevice(w http.ResponseWriter, r *http.Request, id DeviceID)

	// (GET /devices/{id})
	GetDevice(w http.ResponseWriter, r *http.Request, id DeviceID)
	// UpdateDevice Change device settings
	// (PATCH /devices/{id})
	UpdateDevice(w http.ResponseWriter, r *http.Request, id DeviceID)
	// ApproveDevice Activate a pending or disabled device
	// (POST /devices/{id}/approve)
	ApproveDevice(w http.ResponseWriter, r *http.Request, id DeviceID)

	// (DELETE /devices/{id}/calibration)
	StopDeviceCalibration(w http.ResponseWriter, r *http.Request, id DeviceID)
	// StartDeviceCalibration Show the gray calibration pattern on the device for 30 minutes
	// (POST /devices/{id}/calibration)
	StartDeviceCalibration(w http.ResponseWriter, r *http.Request, id DeviceID)

	// (POST /devices/{id}/disable)
	DisableDevice(w http.ResponseWriter, r *http.Request, id DeviceID)
	// ListDeviceLogs Device logs, newest first
	// (GET /devices/{id}/logs)
	ListDeviceLogs(w http.ResponseWriter, r *http.Request, id DeviceID, params ListDeviceLogsParams)
	// SetDevicePlaylist Assign a playlist (or none) and restart the rotation
	// (PUT /devices/{id}/playlist)
	SetDevicePlaylist(w http.ResponseWriter, r *http.Request, id DeviceID)
	// ListDeviceTelemetry Telemetry history, newest first
	// (GET /devices/{id}/telemetry)
	ListDeviceTelemetry(w http.ResponseWriter, r *http.Request, id DeviceID, params ListDeviceTelemetryParams)
	// GetHealth Liveness and dependency status
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListIcons Icons for {{ icon "name" }}; each is also served as /icons/<name>.svg
	// (GET /icons)
	ListIcons(w http.ResponseWriter, r *http.Request)

	// (GET /playlists)
	ListPlaylists(w http.ResponseWriter, r *http.Request)

	// (POST /playlists)
	CreatePlaylist(w http.ResponseWriter, r *http.Request)

	// (DELETE /playlists/{id})
	DeletePlaylist(w http.ResponseWriter, r *http.Request, id PlaylistID)

	// (GET /playlists/{id})
	GetPlaylist(w http.ResponseWriter, r *http.Request, id PlaylistID)
	// UpdatePlaylist Replace name and items (items keep their id when given)
	// (PUT /playlists/{id})
	UpdatePlaylist(w http.ResponseWriter, r *http.Request, id PlaylistID)

	// (GET /screens)
	ListScreens(w http.ResponseWriter, r *http.Request)
	// CreateScreen Create a screen with one full-size region and a starter template
	// (POST /screens)
	CreateScreen(w http.ResponseWriter, r *http.Request)

	// (DELETE /screens/{id})
	DeleteScreen(w http.ResponseWriter, r *http.Request, id ScreenID)

	// (GET /screens/{id})
	GetScreen(w http.ResponseWriter, r *http.Request, id ScreenID)
	// UpdateScreen Save a screen; it re-renders shortly after
	// (PUT /screens/{id})
	UpdateScreen(w http.ResponseWriter, r *http.Request, id ScreenID)

	// (GET /screens/{id}/bindings)
	ListBindings(w http.ResponseWriter, r *http.Request, id ScreenID)
	// ReplaceBindings Replace the screen's bindings (matched by id; omit id for new ones)
	// (PUT /screens/{id}/bindings)
	ReplaceBindings(w http.ResponseWriter, r *http.Request, id ScreenID)
	// GetScreenData Current data of every binding, as templates see it (fetches what is missing)
	// (GET /screens/{id}/data)
	GetScreenData(w http.ResponseWriter, r *http.Request, id ScreenID, params GetScreenDataParams)
	// PreviewScreen Render a screen, optionally with unsaved templates, without storing it
	// (POST /screens/{id}/preview)
	PreviewScreen(w http.ResponseWriter, r *http.Request, id ScreenID)
	// ListScreenRenders Render history, newest first
	// (GET /screens/{id}/renders)
	ListScreenRenders(w http.ResponseWriter, r *http.Request, id ScreenID)
	// RenderScreen Render and store now
	// (POST /screens/{id}/renders)
	RenderScreen(w http.ResponseWriter, r *http.Request, id ScreenID)

	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Change global settings; screens using the defaults are re-rendered
	// (PUT /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)

	// (GET /snippets)
	ListSnippets(w http.ResponseWriter, r *http.Request)

	// (POST /snippets)
	CreateSnippet(w http.ResponseWriter, r *http.Request)

	// (DELETE /snippets/{id})
	DeleteSnippet(w http.ResponseWriter, r *http.Request, id SnippetID)

	// (PUT /snippets/{id})
	UpdateSnippet(w http.ResponseWriter, r *http.Request, id SnippetID)
	// GetSystem Server information the dashboard needs
	// (GET /system)
	GetSystem(w http.ResponseWriter, r *http.Request)
}

